func fuzz() {
extension Trivia {
  fileprivate func indented(indentation: Trivia) -> Trivia {
    let mappedPieces = self. flatMap { (piece) -> [TriviaPiece] in
      if piece.isNewline {
        return [piece] + indentation.pieces
      } else {
        return [piece]
      }
    }
    return Trivia(pieces: mappedPieces)
  }
}
}

